private QuotedPrintableCodec quotedPrintableCodec;

    @Before
    public void init(){
        quotedPrintableCodec = new QuotedPrintableCodec();
    }

    @Test
    public void testDecodeQuotedPrintable_null() throws DecoderException{
        byte[] result = QuotedPrintableCodec.decodeQuotedPrintable(null);
        assertThat(result, is(nullValue()));
    }

    @Test
    public void testDecodeQuotedPrintable_normal() throws DecoderException{
        String str = "Hello World!";
        byte[] bytes = str.getBytes(CharEncoding.UTF_8);
        byte[] result = QuotedPrintableCodec.decodeQuotedPrintable(bytes);
        assertThat(new String(result, CharEncoding.UTF_8), is(str));
    }

    @Test
    public void testDecodeQuotedPrintable_escape() throws DecoderException{
        String str = "Hell=20o World!";
        byte[] bytes = str.getBytes(CharEncoding.UTF_8);
        byte[] result = QuotedPrintableCodec.decodeQuotedPrintable(bytes);
        assertThat(new String(result, CharEncoding.UTF_8), is("Hello World!"));
    }

    @Test
    public void testDecodeQuotedPrintable_softLineBreak() throws DecoderException{
        String str = "Hello=0D=0A World!";
        byte[] bytes = str.getBytes(CharEncoding.UTF_8);
        byte[] result = QuotedPrintableCodec.decodeQuotedPrintable(bytes);
        assertThat(new String(result, CharEncoding.UTF_8), is("Hello World!"));
    }

    @Test
    public void testDecodeQuotedPrintable_invalid() throws DecoderException{
        String str = "Hell=20";
        byte[] bytes = str.getBytes(CharEncoding.UTF_8);
        try {
            QuotedPrintableCodec.decodeQuotedPrintable(bytes);
            Assert.fail();
        } catch (DecoderException e) {
            assertThat(e.getMessage(), is("Invalid quoted-printable encoding"));
        }
    }

    @Test
    public void testDecodeQuotedPrintable_CR() throws DecoderException{
        String str = "Hello\rWorld!";
        byte[] bytes = str.getBytes(CharEncoding.UTF_8);
        byte[] result = QuotedPrintableCodec.decodeQuotedPrintable(bytes);
        assertThat(new String(result, CharEncoding.UTF_8), is("Hello World!"));
    }

    @Test
    public void testDecodeQuotedPrintable_LF() throws DecoderException{
        String str = "Hello\nWorld!";
        byte[] bytes = str.getBytes(CharEncoding.UTF_8);
        byte[] result = QuotedPrintableCodec.decodeQuotedPrintable(bytes);
        assertThat(new String(result, CharEncoding.UTF_8), is("Hello World!"));
    }

    @Test
    public void testEncodeQuotedPrintable() throws DecoderException{
        String str = "Hello World!";
        byte[] bytes = str.getBytes(CharEncoding.UTF_8);
        byte[] result = QuotedPrintableCodec.encodeQuotedPrintable(BitSet.valueOf(new long[]{0x00000000000000ff}), bytes);
        assertThat(result, notNullValue());
    }

    @Test
    public void testEncode() throws EncoderException{
        String str = "Hello World!";
        byte[] bytes = str.getBytes(CharEncoding.UTF_8);
        byte[] result = quotedPrintableCodec.encode(bytes);
        assertThat(result, notNullValue());
    }

    @Test
    public void testDecode() throws DecoderException{
        String str = "Hello=20World!";
        byte[] bytes = str.getBytes(CharEncoding.UTF_8);
        byte[] result = quotedPrintableCodec.decode(bytes);
        assertThat(new String(result, CharEncoding.UTF_8), is("Hello World!"));
    }

    @Test
    public void testEncode_String() throws EncoderException{
        String str = "Hello World!";
        String result = quotedPrintableCodec.encode(str);
        assertThat(result, notNullValue());
    }

    @Test
    public void testDecode_String() throws DecoderException{
        String str = "Hello=20World!";
        String result = quotedPrintableCodec.decode(str);
        assertThat(result, is("Hello World!"));
    }

    @Test
    public void testGetDefaultCharset(){
        String result = quotedPrintableCodec.getDefaultCharset();
        assertThat(result, is(CharEncoding.UTF_8));
    }

    @Test
    public void testEncode_String_Charset() throws UnsupportedEncodingException, EncoderException{
        String str = "Hello World!";
        String result = quotedPrintableCodec.encode(str, CharEncoding.UTF_8);
        assertThat(result, notNullValue());
    }
}
