    public void testEncodeBase64_Success(){
        byte[] input = {1, 2, 3};
        byte[] result = Base64.encodeBase64(input);
        Assert.assertNotNull(result);
        Assert.assertTrue(result.length > 0);
    }

    @Test
    public void testEncodeBase64URLSafe_Success(){
        byte[] input = {1, 2, 3};
        byte[] result = Base64.encodeBase64URLSafe(input);
        Assert.assertNotNull(result);
        Assert.assertTrue(result.length > 0);
    }

    @Test
    public void testEncodeBase64Chunked_Success(){
        byte[] input = {1, 2, 3};
        byte[] result = Base64.encodeBase64Chunked(input);
        Assert.assertNotNull(result);
        Assert.assertTrue(result.length > 0);
    }

    @Test
    public void testIsBase64_Success(){
        Assert.assertTrue(Base64.isBase64((byte) 'A'));
    }

    @Test
    public void testIsArrayByteBase64_Success(){
        byte[] input = {'A', 'B', 'C'};
        Assert.assertTrue(Base64.isArrayByteBase64(input));
    }

    @Test
    public void testDecode_Success() throws DecoderException{
        byte[] input = Base64.encodeBase64(new byte[]{1, 2, 3});
        Object result = base64.decode(input);
        Assert.assertNotNull(result);
        Assert.assertTrue(result instanceof byte[]);
    }

    @Test(expected = DecoderException.class)
    public void testDecode_Fail() throws DecoderException{
        base64.decode("not a byte array");
    }

    @Test
    public void testDecodeBase64_Success(){
        byte[] input = Base64.encodeBase64(new byte[]{1, 2, 3});
        byte[] result = Base64.decodeBase64(input);
        Assert.assertNotNull(result);
        Assert.assertTrue(result.length > 0);
    }

    @Test
    public void testDiscardWhitespace_Success(){
        byte[] input = {' ', 'A', 'B', 'C'};
        byte[] result = Base64.discardWhitespace(input);
        Assert.assertNotNull(result);
        Assert.assertEquals(3, result.length);
    }

    @Test
    public void testDiscardNonBase64_Success(){
        byte[] input = {' ', 'A', 'B', 'C'};
        byte[] result = Base64.discardNonBase64(input);
        Assert.assertNotNull(result);
        Assert.assertEquals(3, result.length);
    }

    @Test
    public void testDecodeInteger_Success(){
        byte[] input = Base64.encodeBase64(new byte[]{1, 2, 3});
        BigInteger result = Base64.decodeInteger(input);
        Assert.assertNotNull(result);
    }

    @Test
    public void testEncodeInteger_Success(){
        BigInteger input = BigInteger.valueOf(10);
        byte[] result = Base64.encodeInteger(input);
        Assert.assertNotNull(result);
        Assert.assertTrue(result.length > 0);
    }

    @Test
    public void testToIntegerBytes_Success(){
        BigInteger input = BigInteger.valueOf(10);
        byte[] result = Base64.toIntegerBytes(input);
        Assert.assertNotNull(result);
        Assert.assertTrue(result.length > 0);
    }
}
